    id_val=m.group(1)
    status='Legal'
    for s in ['Restricted','Banned']:
        if s in m.group(0): status=s; break
    cards_id=re.search(r'cards_id\s+(\d+)',m.group(0))
    if cards_id:
        snippet=m.group(0).lower()
        if 'commander' in snippet:
            entries.append((id_val, cards_id.group(1), status))
    else:
        # Look ahead 200 chars from end of match
        lookbehind=content[max(0,m.start()-1000):m.start()]
        if 'commander' in lookbehind.lower():
            entries.append((id_val, 'NA', status))
print(f'Found {len(entries)} entries')
for e in entries[:5]:
    print(e)

